package com.example.eac_backend_project.communication;
import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.beans.factory.annotation.Value;import org.springframework.jdbc.core.JdbcTemplate;import com.fasterxml.jackson.databind.*;import jakarta.persistence.*;import java.util.*;import java.io.*;import java.nio.file.*;import java.time.*;import java.security.MessageDigest;import static com.example.eac_backend_project.communication.CommunicationAccess.fail;
@Service @Transactional(rollbackFor=Exception.class) public class CommunicationBackupService {
 private final CommunicationService service;private final CommunicationBackupRepository backups;private final CommunicationAuditRepository audit;private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final Path root;private final org.springframework.transaction.support.TransactionTemplate taskTransaction;
 public CommunicationBackupService(CommunicationService service,CommunicationBackupRepository backups,CommunicationAuditRepository audit,JdbcTemplate jdbc,ObjectMapper mapper,org.springframework.transaction.PlatformTransactionManager transactions,@Value("${app.communication.backup-root:./backups/communication}")String root){this.taskTransaction=new org.springframework.transaction.support.TransactionTemplate(transactions);this.service=service;this.backups=backups;this.audit=audit;this.jdbc=jdbc;this.mapper=mapper;this.root=Path.of(root).toAbsolutePath().normalize();}
 private void permit(String reason){var u=service.access().account();service.authorizeReview(u,"COMMUNICATION_BACKUP_MANAGE",reason,null,"BACKUP_ACCESS");}
 public List<CommunicationBackup> list(String reason){permit(reason);return backups.findAll(org.springframework.data.domain.Sort.by(org.springframework.data.domain.Sort.Direction.DESC,"createdAt"));}
 public CommunicationBackup create(String reason)throws IOException{permit(reason);return build(service.access().account().getId());}
 private List<Map<String,Object>> rows(List<?> entities)throws IOException{List<Map<String,Object>> rows=new ArrayList<>();for(Object entity:entities){Map<String,Object> row=new LinkedHashMap<>();try{for(var field:entity.getClass().getFields()){Object value=field.get(entity);String column=field.isAnnotationPresent(Column.class)&&!field.getAnnotation(Column.class).name().isEmpty()?field.getAnnotation(Column.class).name():snake(field.getName());if(field.isAnnotationPresent(ManyToOne.class)){column=field.getAnnotation(JoinColumn.class).name();value=value instanceof CommunicationConversation c?c.id:((com.example.eac_backend_project.entity.inventory.User)value).getId();}row.put(column,value);}}catch(ReflectiveOperationException e){throw new IOException("Backup metadata unavailable");}rows.add(row);}return rows;}
 private static String snake(String s){return s.replaceAll("([a-z])([A-Z])","$1_$2").toLowerCase(Locale.ROOT);}
 @Transactional public synchronized CommunicationBackup build(Long actor)throws IOException{
  if(!service.crypto().available())throw fail(503,"Communication encryption key not configured");CommunicationBackup record=new CommunicationBackup();record.id=UUID.randomUUID().toString();record.actorId=actor;record.expiresAt=Instant.now().plusSeconds(service.config().backupRetentionDays*86400L);record.status="CREATING";backups.saveAndFlush(record);
  try{if(service.messages().count()>100000)throw fail(413,"Use infrastructure backup for more than 100000 messages");var allMessages=service.messages().findAll();Set<Long> ids=new HashSet<>();for(var m:allMessages)for(var f:service.body(m).path("attachments"))ids.add(f.path("fileId").asLong());Map<String,Object> manifest=CommunicationService.map("format","eac-communication-backup","version",1,"createdAt",Instant.now(),"conversations",rows(service.conversations().findAll()),"participants",rows(service.participants().findAll()),"messages",rows(allMessages),"uploads",rows(service.uploads().findAll()),"policy",rows(service.policies().findAll()),"audit",rows(audit.findAll()),"files",service.files().snapshot(ids));byte[] plain=mapper.writeValueAsBytes(manifest);if(plain.length>180*1024*1024)throw fail(413,"Communication backup exceeds 180 MB; use infrastructure backup");byte[] encrypted=service.crypto().seal(plain,"backup:"+record.id);Files.createDirectories(root);Path path=path(record.id);Files.write(path,encrypted,StandardOpenOption.CREATE_NEW);record.sizeBytes=encrypted.length;record.checksum=hash(encrypted);record.status="VERIFIED";backups.saveAndFlush(record);return record;
  }catch(Exception ex){record.status="FAILED";record.error="Backup failed; verify encryption configuration and storage availability";backups.saveAndFlush(record);return record;}
 }
 private Path path(String id){if(id==null||!id.matches("[a-f0-9-]{36}"))throw fail(400,"Invalid backup identifier");return root.resolve(id+".eacbackup");}
 private static String hash(byte[] bytes){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException("Checksum unavailable");}}
 private JsonNode archive(String id)throws IOException{var record=backups.findById(id).orElseThrow(()->fail(404,"Backup not found"));if(!Files.isRegularFile(path(id)))throw fail(404,"Backup data unavailable");if(Files.size(path(id))>200*1024*1024)throw fail(413,"Backup exceeds verification limit");byte[] encrypted=Files.readAllBytes(path(id));if(!Objects.equals(record.checksum,hash(encrypted)))throw fail(409,"Backup integrity check failed");JsonNode manifest=mapper.readTree(service.crypto().open(encrypted,"backup:"+id));if(!"eac-communication-backup".equals(manifest.path("format").asText())||manifest.path("version").asInt()!=1)throw fail(400,"Unsupported backup format");return manifest;}
 public Map<String,Object> verify(String id,String reason)throws IOException{permit(reason);var data=archive(id);return CommunicationService.map("id",id,"verified",true,"messages",data.path("messages").size(),"files",data.path("files").size());}
 public Map<String,Object> preview(String id,String reason)throws IOException{permit(reason);var data=archive(id);long missing=0;for(var row:data.path("messages"))if(!service.messages().existsById(row.path("id").asLong()))missing++;return CommunicationService.map("id",id,"missingMessages",missing,"backupMessages",data.path("messages").size(),"confirmation",backups.findById(id).orElseThrow().checksum,"impact","Restore missing records and missing file versions only. Existing messages, memberships, policy and file records will not be overwritten. Missing managed files include their folder ancestry and grants. Current file permissions are never overwritten.");}
 private void insertMissing(String table,JsonNode row,Class<?> type){long id=row.path("id").asLong();Integer count=jdbc.queryForObject("select count(*) from "+table+" where id=?",Integer.class,id);if(count!=null&&count>0)return;List<String> columns=new ArrayList<>();List<Object> values=new ArrayList<>();for(var field:type.getFields()){String column=field.isAnnotationPresent(Column.class)&&!field.getAnnotation(Column.class).name().isEmpty()?field.getAnnotation(Column.class).name():snake(field.getName());if(field.isAnnotationPresent(ManyToOne.class))column=field.getAnnotation(JoinColumn.class).name();JsonNode value=row.get(column);columns.add(column);Object v=null;if(value!=null&&!value.isNull()){if(field.getType()==Instant.class)v=java.sql.Timestamp.from(Instant.parse(value.asText()));else if(field.getType()==byte[].class)v=Base64.getDecoder().decode(value.asText());else if(field.getType()==boolean.class)v=value.asBoolean();else if(field.getType()==long.class||field.getType()==Long.class||field.isAnnotationPresent(ManyToOne.class))v=value.asLong();else if(field.getType()==int.class)v=value.asInt();else v=value.asText();}values.add(v);}jdbc.update("insert into "+table+" ("+String.join(",",columns)+") values ("+String.join(",",Collections.nCopies(columns.size(),"?"))+")",values.toArray());}
 public Map<String,Object> restore(String id,String reason,String confirmation)throws IOException{permit(reason);var record=backups.findById(id).orElseThrow();if(!Objects.equals(record.checksum,confirmation))throw fail(409,"Review the backup impact summary before confirming restore");var data=archive(id);service.policies().lock().orElseThrow();Set<Long> newConversations=new HashSet<>();for(var c:data.path("conversations"))if(!service.conversations().existsById(c.path("id").asLong())){insertMissing("communication_conversations",c,CommunicationConversation.class);newConversations.add(c.path("id").asLong());}for(var p:data.path("participants"))if(newConversations.contains(p.path("conversation_id").asLong())&&service.users().existsById(p.path("user_id").asLong()))insertMissing("communication_participants",p,CommunicationParticipant.class);service.files().restoreSnapshot(data.path("files"));for(var upload:data.path("uploads"))insertMissing("communication_uploads",upload,CommunicationUpload.class);int restored=0;for(var m:data.path("messages")){Long conversation=m.path("conversation_id").asLong();if(service.messages().existsById(m.path("id").asLong())||!service.users().existsById(m.path("sender_id").asLong()))continue;service.lock(conversation);Integer collision=jdbc.queryForObject("select count(*) from communication_messages where conversation_id=? and sequence_number=?",Integer.class,conversation,m.path("sequence_number").asLong());if(collision!=null&&collision>0)continue;insertMissing("communication_messages",m,CommunicationMessage.class);jdbc.update("update communication_conversations set last_sequence=greatest(last_sequence,?) where id=?",m.path("sequence_number").asLong(),conversation);restored++;}service.audit().write(service.access().account(),"BACKUP_RESTORE",null,reason,"backup="+id+",restoredMessages="+restored);return CommunicationService.map("restoredMessages",restored,"overwrittenMessages",0);}
 @Scheduled(initialDelayString="${app.communication.backup-initial-delay-ms:60000}",fixedDelayString="${app.communication.backup-poll-ms:3600000}") public void scheduled(){try{taskTransaction.executeWithoutResult(status->{if(!service.crypto().available()||!service.config().backupsEnabled)return;Instant cutoff=Instant.now().minusSeconds(service.config().backupIntervalHours*3600L);if(backups.findAll().stream().anyMatch(b->"VERIFIED".equals(b.status)&&b.createdAt.isAfter(cutoff)))return;try{build(null);}catch(IOException e){throw new java.io.UncheckedIOException(e);}});}catch(Exception ex){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Scheduled communication backup failed; inspect protected backup storage");}}
}
